INSERT INTO Products (Name, Description, Price, QuantityAvailable, ImagePath, CategoryId) VALUES
('Authentic 70mm IMAX film cell Dark Knight IMAX Film Cell', 'A genuine 70mm IMAX film cell from The Dark Knight, showcasing a single frame from its groundbreaking large-format presentation. A rare collectible celebrating Christopher Nolan’s revolutionary approach to modern cinema.', 119.99, 10, '/AbsoluteCinemaImages/DarkKnightRises.jpg', 1),
('Lalo Schifrin’s iconic theme Mission: Impossible Theme Vinyl', 'Featuring Lalo Schifrin’s iconic theme, this vinyl captures one of the most recognizable scores in film and television history. Its driving rhythm and suspenseful tone define the classic spy genre.', 89.99, 5, '/AbsoluteCinemaImages/MissionImpossibleVinyl.jpg', 1),
('Life-size T-800 endoskeleton hand replica Terminator 2 Metal Endoskeleton Hand', 'A life-size replica of the T-800 endoskeleton hand from Terminator 2: Judgment Day. This detailed piece reflects the film’s iconic mechanical design and sci-fi legacy.', 249.99, 7, '/AbsoluteCinemaImages/Terminator2Arm.jpg', 1),
('Aged Map Replica Indian Jones Map Replica', 'An aged replica map inspired by the Indiana Jones adventure films. Designed with weathered details, it captures the spirit of exploration and cinematic archaeology.', 64.99, 12, '/AbsoluteCinemaImages/AgedIndianaJonesMap.jpg', 2),
('Complete Trilogy Soundtrack The Lord of the Rings Soundtrack', 'The complete soundtrack collection from The Lord of the Rings trilogy, composed by Howard Shore. These scores bring the world of Middle-earth to life through sweeping and memorable themes.', 79.99, 9, '/AbsoluteCinemaImages/LordofTheRingsSoundtrack.jpg', 2),
('Jack Sparrow’s Compass Replica Pirates of the Caribbean Compass', 'A replica of Jack Sparrow’s enchanted compass from Pirates of the Caribbean. Unlike a traditional compass, it points to what the holder desires most.', 129.99, 15, '/AbsoluteCinemaImages/JackSparrowCompass.jpg', 2),
('Vintage-style poster from Kubrick The Shining Overlook Hotel Poster', 'A vintage-style poster inspired by Stanley Kubrick’s The Shining. Featuring the Overlook Hotel, it reflects the film’s eerie atmosphere and psychological tension.', 54.99, 8, '/AbsoluteCinemaImages/TheShiningHotelPoster.jpg', 3),
('John Carpenter’s iconic theme on 7" vinyl Halloween Theme Vinyl 45rpm', 'A 7-inch vinyl pressing of John Carpenter’s iconic Halloween theme. Its minimalist, haunting sound helped define modern horror cinema.', 29.99, 16, '/AbsoluteCinemaImages/HalloweenThemeVinyl.jpg', 3),
('Official Freddy Krueger glove replica A Nightmare on Elm Street Glove Replica', 'An official replica of Freddy Krueger’s signature bladed glove. This piece represents one of horror cinema’s most recognizable and chilling symbols.', 199.99, 4, '/AbsoluteCinemaImages/FreddyKruegerGlove.jpg', 3),
('Limited edition art prints Blade Runner 2049', 'Limited edition art prints inspired by Blade Runner 2049. The designs reflect the film’s futuristic visuals and neo-noir aesthetic.', 74.99, 9, '/AbsoluteCinemaImages/BladeRunner2049.jpg', 4),
('A New Hope complete score Star Wars Original Soundtrack', 'The complete score from Star Wars: Episode IV – A New Hope, composed by John Williams. Featuring legendary themes that launched one of cinema’s most iconic franchises.', 59.99, 10, '/AbsoluteCinemaImages/StarWarsOriginalSoundtrack.jpg', 4),
('Red and Blue pill replicas The Matrix Red Pill Prop Replica', 'Replica versions of the red and blue pills from The Matrix. These props symbolize the film’s central choice between illusion and reality.', 39.99, 15, '/AbsoluteCinemaImages/TheMatrixPill.jpg', 4),
('Original cast recording remastered The Sound of Music Deluxe Vinyl', 'A remastered deluxe vinyl of the original cast recording from The Sound of Music. Featuring timeless songs from one of the most beloved musicals of all time.', 39.99, 13, '/AbsoluteCinemaImages/TheSoundOfMusicDeluxeVinyl.jpg', 5),
('Authenticated poster with cast signatures Grease Signed Movie Poster', 'An authenticated Grease movie poster featuring cast signatures. A collectible celebrating the enduring legacy of the classic musical film.', 299.99, 7, '/AbsoluteCinemaImages/GreaseSignedMoviePoster.jpg', 5),
('Award-winning score La La Land Soundtrack Vinyl', 'The award-winning soundtrack from La La Land, composed by Justin Hurwitz. Blending jazz and orchestral elements, it captures the film’s themes of love, ambition, and creativity.', 34.99, 8, '/AbsoluteCinemaImages/LaLaLandSoundtrackVinyl.jpg', 5);